const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

function parseTikTok(rawBody) {
  if (!rawBody || typeof rawBody !== 'object') return null;
  // Assuming a structure similar to the previous implementation as a starting point
  const entry = rawBody.entry?.[0];
  if (!entry) return null;
  const change = entry.changes?.[0];
  if (!change) return null;
  const val = change.value || {};

  if (val.message_id === undefined && val.sender_id === undefined) return null;

  return {
    provider: 'tiktok',
    msg_id: val.message_id || val.mid || crypto.randomUUID(),
    from: val.sender_id || '',
    text: val.message?.text || '',
    timestamp: new Date().toISOString(),
    attachments: [],
    meta: {
      recipient_id: val.recipient_id || '',
      campaign: val.referral_param || ''
    }
  };
}

const rawBodyInput = $json.body ?? $json;
const parsed = parseTikTok(rawBodyInput);

const headers = ($json.headers ?? {});
const ipRaw = (headers['x-forwarded-for'] || '').toString();
const ip = ipRaw.split(',')[0].trim();
const inboundReceivedAt = new Date().toISOString();
const correlationId = (headers['x-correlation-id'] || crypto.randomUUID()).toString();

const token = (headers['x-api-token'] || '').toString().trim();
const tokenHash = token ? crypto.createHash('sha256').update(token).digest('hex') : '';

const envelope = parsed ? {
  contract_version: 'v1',
  provider: 'tiktok',
  msg_id: parsed.msg_id,
  from: parsed.from,
  text: parsed.text,
  timestamp: parsed.timestamp,
  attachments: [],
  meta: { ...parsed.meta, ip }
} : null;

return [{
  json: {
    channel: 'tiktok',
    userId: parsed?.from || 'unknown',
    tenantId: '',
    restaurantId: '',
    conversationKey: '',
    inbound_envelope: envelope,
    metadata: {
      msgId: parsed?.msg_id || crypto.randomUUID(),
      timestamp: inboundReceivedAt,
      ip,
      userAgent: (headers['user-agent'] || '').toString()
    },
    message: {
      type: 'text',
      text: (parsed?.text || '').toString().trim()
    },
    _auth: {
      tokenPresent: !!token,
      tokenHash
    },
    _timing: {
      inbound_received_at: inboundReceivedAt,
      correlation_id: correlationId
    },
    _sec: {
      textHash: crypto.createHash('sha256').update(parsed?.text || '').digest('hex')
    }
  }
}];

const e = $json;
const matched = !!e.matched;
let tenantId = e.tenant_id || '';
let restaurantId = e.restaurant_id || '';
let authMode = matched ? 'api_client' : 'deny';
let scopes = [];
try { scopes = Array.isArray(e.scopes) ? e.scopes : JSON.parse(e.scopes || '[]'); } catch { scopes = []; }

const conversationKey = tenantId ? `${tenantId}:${restaurantId}:tiktok:${e.userId}` : '';
const authOk = authMode !== 'deny';
const scopeOk = authOk && (scopes.includes('inbound:write') || scopes.includes('*'));

const tenant_context = {
  tenant_id: tenantId || null,
  restaurant_id: restaurantId || null,
  source: authMode,
  scopes
};

return [{
  json: {
    ...e,
    tenantId,
    restaurantId,
    conversationKey,
    tenant_context,
    _auth: {
      ...e._auth,
      authOk,
      scopeOk,
      denyReason: authOk ? (scopeOk ? '' : 'SCOPE_DENY') : 'AUTH_DENY'
    }
  }
}];

const crypto = require('crypto');
const e = $json;
const ctx = e.tenant_context || {};
const secret = ($env.TENANT_CONTEXT_SECRET || 'fallback-secret-6789').toString();
const seal = crypto.createHmac('sha256', secret).update(JSON.stringify(ctx)).digest('hex');
return [{json:{...e, tenant_context_seal: seal}}];

